BEGIN;
SELECT plan(32);
INSERT INTO households(id,name)VALUES('e4000000-0000-4000-8000-000000000001','synthetic custom A'),('e4000000-0000-4000-8000-000000000002','synthetic custom B');
INSERT INTO auth.users(id,email)VALUES('e4000000-0000-4000-8000-000000000003','custom-a@example.invalid'),('e4000000-0000-4000-8000-000000000004','custom-b@example.invalid');
UPDATE profiles SET household_id='e4000000-0000-4000-8000-000000000001',is_approved=true,role='owner' WHERE id='e4000000-0000-4000-8000-000000000003';
UPDATE profiles SET household_id='e4000000-0000-4000-8000-000000000002',is_approved=true WHERE id='e4000000-0000-4000-8000-000000000004';
INSERT INTO children(id,household_id,name)VALUES('e4000000-0000-4000-8000-000000000005','e4000000-0000-4000-8000-000000000001','synthetic custom sibling');
CREATE TEMP TABLE cf(value jsonb);GRANT ALL ON cf TO authenticated;
CREATE TEMP TABLE cr(value jsonb);GRANT ALL ON cr TO authenticated;
CREATE TEMP TABLE cs(value jsonb);GRANT ALL ON cs TO authenticated;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"e4000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
INSERT INTO cf SELECT save_custom_field('e4000000-0000-4000-8000-000000000010',NULL,'synthetic number','number','[]',false);
SELECT is((SELECT value->>'status' FROM cf),'saved','household defines numeric field');
INSERT INTO cr SELECT save_custom_record('e4000000-0000-4000-8000-000000000020',(SELECT id FROM children WHERE is_legacy),NULL,'e4000000-0000-4000-8000-000000000010','0',now(),'synthetic memo',false);
SELECT is((SELECT value->>'status' FROM cr),'saved','zero is a valid numeric record');
SELECT is((save_custom_record('e4000000-0000-4000-8000-000000000020',(SELECT id FROM children WHERE is_legacy),NULL,'e4000000-0000-4000-8000-000000000010','0',now(),'synthetic memo',false)->>'status'),'replayed','same operation confirms exact existing payload');
SELECT throws_ok($$SELECT save_custom_record('e4000000-0000-4000-8000-000000000021',(SELECT id FROM children WHERE is_legacy),NULL,'e4000000-0000-4000-8000-000000000010','"string"',now(),NULL,false)$$,'22023',NULL,'typed number rejects strings');
SELECT is((save_custom_record('e4000000-0000-4000-8000-000000000020',(SELECT id FROM children WHERE is_legacy),'2020-01-01','e4000000-0000-4000-8000-000000000010','2',now(),NULL,false)->>'status'),'conflict','stale record cannot overwrite');
SELECT throws_ok($$SELECT save_custom_record('e4000000-0000-4000-8000-000000000020','e4000000-0000-4000-8000-000000000005',NULL,'e4000000-0000-4000-8000-000000000010','0',now(),NULL,false)$$,'42501',NULL,'record cannot move to sibling');
SELECT is((save_custom_field('e4000000-0000-4000-8000-000000000011',NULL,'synthetic bool','boolean','[]',false)->>'status'),'saved','boolean field created');
SELECT is((save_custom_record('e4000000-0000-4000-8000-000000000021',(SELECT id FROM children WHERE is_legacy),NULL,'e4000000-0000-4000-8000-000000000011','false',now(),NULL,false)->>'status'),'saved','false is a valid boolean');
SELECT save_custom_field('e4000000-0000-4000-8000-000000000012',NULL,'synthetic text','text','[]',false);
SELECT is((save_custom_record('e4000000-0000-4000-8000-000000000022',(SELECT id FROM children WHERE is_legacy),NULL,'e4000000-0000-4000-8000-000000000012','"synthetic text value"',now(),NULL,false)->>'status'),'saved','text record saved');
SELECT save_custom_field('e4000000-0000-4000-8000-000000000013',NULL,'synthetic date','datetime','[]',false);
SELECT is((save_custom_record('e4000000-0000-4000-8000-000000000023',(SELECT id FROM children WHERE is_legacy),NULL,'e4000000-0000-4000-8000-000000000013','"2026-01-01T00:00:00Z"',now(),NULL,false)->>'status'),'saved','datetime record saved');
SELECT throws_ok($$SELECT save_custom_record('e4000000-0000-4000-8000-000000000024',(SELECT id FROM children WHERE is_legacy),NULL,'e4000000-0000-4000-8000-000000000013','"now"',now(),NULL,false)$$,'22023',NULL,'relative time strings rejected');
SELECT save_custom_field('e4000000-0000-4000-8000-000000000014',NULL,'synthetic choice','choice','["A","B"]',false);
SELECT is((save_custom_record('e4000000-0000-4000-8000-000000000024',(SELECT id FROM children WHERE is_legacy),NULL,'e4000000-0000-4000-8000-000000000014','"A"',now(),NULL,false)->>'status'),'saved','choice record saved');
SELECT throws_ok($$SELECT save_custom_record('e4000000-0000-4000-8000-000000000025',(SELECT id FROM children WHERE is_legacy),NULL,'e4000000-0000-4000-8000-000000000014','"C"',now(),NULL,false)$$,'22023',NULL,'choice outside definition rejected');
SELECT throws_ok($$SELECT save_custom_field('e4000000-0000-4000-8000-000000000015',NULL,'duplicate choice','choice','["A","A"]',false)$$,'22023',NULL,'duplicate choices rejected');
SELECT throws_ok($$SELECT save_custom_field('e4000000-0000-4000-8000-000000000010',now(),'changed type','text','[]',false)$$,'22023',NULL,'historical type cannot be reinterpreted');
UPDATE cf SET value=save_custom_field('e4000000-0000-4000-8000-000000000010',(value->'field'->>'updated_at')::timestamptz,'synthetic renamed','number','[]',true);
SELECT is((SELECT field_label FROM custom_records WHERE id='e4000000-0000-4000-8000-000000000020'),'synthetic number','rename keeps recorded label snapshot');
SELECT throws_ok($$SELECT save_custom_record('e4000000-0000-4000-8000-000000000025',(SELECT id FROM children WHERE is_legacy),NULL,'e4000000-0000-4000-8000-000000000010','1',now(),NULL,false)$$,'42501',NULL,'archived field refuses new records');
SELECT is((save_custom_record('e4000000-0000-4000-8000-000000000020',(SELECT id FROM children WHERE is_legacy),(SELECT value->'record'->>'updated_at' FROM cr)::timestamptz,'e4000000-0000-4000-8000-000000000010','3',now(),NULL,true)->>'status'),'saved','archived record remains editable and voidable');
SELECT is((SELECT count(*) FROM custom_records),5::bigint,'archive and void do not delete history');
SELECT is((SELECT count(*) FROM custom_records WHERE search_text ILIKE '%synthetic text value%'),1::bigint,'record value is searchable');
SELECT is((export_child_records((SELECT id FROM children WHERE is_legacy))->>'row_count'),'5','single snapshot export includes all archived and voided rows');
SELECT throws_ok($$UPDATE custom_records SET value='999'$$,'42501',NULL,'no direct write grant');
SELECT throws_ok($$DELETE FROM custom_fields$$,'42501',NULL,'definition history has no delete grant');
INSERT INTO cs SELECT create_child_share((SELECT id FROM children WHERE is_legacy),false,false,false,true,NULL);
SELECT set_config('request.jwt.claims','{"sub":"e4000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM custom_records),0::bigint,'foreign household cannot read records');
SELECT is((SELECT count(*) FROM custom_fields),0::bigint,'foreign household cannot read definitions');
SELECT throws_ok($$SELECT export_child_records('e4000000-0000-4000-8000-000000000005')$$,'42501',NULL,'foreign export denied');
SELECT accept_child_share((SELECT value->>'token' FROM cs));
SELECT is((SELECT jsonb_array_length(shared_child_snapshot((value->>'id')::uuid)->'custom') FROM cs),4,'explicit custom share returns selected nonvoided records only');
RESET ROLE;
SELECT ok(NOT has_function_privilege('anon','public.export_child_records(uuid,date,date)','EXECUTE'),'anon has no export RPC grant');
UPDATE profiles SET role='viewer' WHERE id='e4000000-0000-4000-8000-000000000003';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"e4000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM custom_records),0::bigint,'viewer cannot read raw records');
SELECT throws_ok($$SELECT save_custom_field('e4000000-0000-4000-8000-000000000019',NULL,'viewer attempt','text','[]',false)$$,'42501',NULL,'viewer cannot define fields');
SELECT throws_ok($$SELECT save_custom_record('e4000000-0000-4000-8000-000000000029','e4000000-0000-4000-8000-000000000005',NULL,'e4000000-0000-4000-8000-000000000010','1',now(),NULL,false)$$,'42501',NULL,'viewer cannot write a record');
SELECT throws_ok($$SELECT export_child_records('e4000000-0000-4000-8000-000000000005')$$,'42501',NULL,'viewer cannot export records');
RESET ROLE;
SELECT * FROM finish();ROLLBACK;
